              className={`rounded-full cursor-pointer h-2 transition-[width,background-color] duration-300 ${activeIndex === i ? 'w-7 bg-current' : 'w-2 bg-current/30 hover:bg-current/50'}`}>
            </div>
          ))}
        </div>

        {/* next button */}
        <button 
          onClick={toNext} 
